func:
// Single point of entry. The server-events node's own event_type filter is not
// honoured by every version of node-red-contrib-home-assistant-websocket, so this
// flow subscribes once to the bus and does the filtering and dispatch itself.
//
// Everything that is not one of this integration's events is dropped here, in one
// cheap string comparison -- rather than waking eight separate function nodes for
// every state_changed in Home Assistant.
const raw = msg.payload || {};
const type = raw.event_type || msg.topic || '';

if (type.lastIndexOf('ha_stock_app_', 0) !== 0) return null;

const ROUTE = {
    'ha_stock_app_price_alert': 0,
    'ha_stock_app_eod_summary': 1,
    'ha_stock_app_market_open': 2,
    'ha_stock_app_eod2_summary': 3,
    'ha_stock_app_paycheck_detected': 4,
    'ha_stock_app_monarch_status': 5,
    'ha_stock_app_finnhub_error': 6,
    'ha_stock_app_finnhub_ok': 7
};
const idx = ROUTE[type];
if (idx === undefined) return null;   // ours, but nothing is wired to it

// Payload is the bare event data on some versions, the full envelope on others.
msg.payload = raw.event || raw.data || raw;
msg.topic = type;

const out = new Array(8).fill(null);
out[idx] = msg;
return out;

const d = msg.payload || {};
const TEST = d.test === true;

// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.symbol === undefined || d.change_pct === undefined || d.price === undefined) {
    node.warn('price_alert: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 parity: icon/sign/channel/colour, and the "Level crossed" figure, which v2
// derived as sign * floor(|pct| / 1.0) * 1.0 with a 1% threshold.
const sym   = d.symbol;
const price = Number(d.price);
const pct   = Number(d.change_pct);
const icon  = pct >= 0 ? '\u{1F7E2}' : '\u{1F534}';
const sign  = pct >= 0 ? '+' : '';
const level = (pct >= 0 ? 1 : -1) * Math.floor(Math.abs(pct) / 1.0) * 1.0;
const label = sym === 'VOO' ? 'VOO (S&P 500)' : sym;

msg.payload = {
    title:   `${icon} ${label} ${sign}${pct.toFixed(2)}% today`,
    message: `${sym} at $${price.toFixed(2)} \u2014 ${sign}${pct.toFixed(2)}% vs prev close. Level crossed: ${sign}${level}%`,
    color:   pct >= 0 ? 'green' : 'red',
    channel: pct <= -2 ? 'stock_alert' : 'Stocks',
    test:    TEST,
    // v2 alerted once per whole-percent level and no more than hourly.
    dedupKey: `price:${sym}:${level}`,
    cooldownMs: 60 * 60 * 1000
};
return msg;

const d = msg.payload || {};
const TEST = d.test === true;

// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (!d.stocks || Object.keys(d.stocks).length === 0) {
    node.warn('eod_summary: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 parity: per-line "icon LABEL  $price  +pct%  |  $held  (+$day)", then a
// total line. v2 read holdings from Monarch sensors; the integration now ships
// position_value/day_pl in the event itself.
const stocks = d.stocks || {};
const syms = Object.keys(stocks);

function fmtMoney(val) {
    if (val == null || isNaN(val)) return null;
    return '$' + Math.abs(Math.round(val)).toLocaleString('en-US');
}

let totalHeld = 0, totalDay = 0, haveHeld = false;
const lines = syms.map(sym => {
    const s = stocks[sym];
    const price = Number(s.price), pct = Number(s.change_pct);
    if (isNaN(price) || isNaN(pct)) return `${sym}: no data`;
    const icon = pct >= 0 ? '\u{1F7E2}' : '\u{1F534}';
    const pctSign = pct >= 0 ? '+' : '-';
    let line = `${icon} ${sym}  $${price.toFixed(2)}  ${pctSign}${Math.abs(pct).toFixed(2)}%`;
    if (s.position_value != null && s.day_pl != null) {
        haveHeld = true;
        totalHeld += Number(s.position_value);
        totalDay  += Number(s.day_pl);
        const dcSign = Number(s.day_pl) >= 0 ? '+' : '-';
        line += `  |  ${fmtMoney(s.position_value)}  (${dcSign}${fmtMoney(s.day_pl)})`;
    }
    return line;
});

// v2 badged the summary off the S&P proxy; fall back to the first symbol.
const lead = stocks['VOO'] || stocks[syms[0]];
const leadPct = lead ? Number(lead.change_pct) : null;
let badge = '\u{1F4CA}';
if (leadPct != null && !isNaN(leadPct)) {
    if      (leadPct >= 1)  badge = '\u{1F7E2}';
    else if (leadPct >= 0)  badge = '\u{1F7E1}';
    else if (leadPct >= -1) badge = '\u{1F7E0}';
    else                    badge = '\u{1F534}';
}
// Handed to the 401k formatter, which fires minutes later and wants this figure.
if (leadPct != null && !isNaN(leadPct)) flow.set('lead_pct', leadPct);

const parts = lines.slice();
if (haveHeld) {
    const sign = totalDay >= 0 ? '+' : '-';
    parts.push('', `\u{1F4BC} Total: ${fmtMoney(totalHeld)}  |  Day: ${sign}${fmtMoney(totalDay)}`);
}

msg.payload = {
    title:   `${badge} Market Closed \u2014 Daily Summary`,
    message: parts.join('\n'),
    color:   (leadPct != null && leadPct >= 0) ? 'green' : 'red',
    channel: 'Stocks',
    test:    TEST
};
return msg;

const d = msg.payload || {};
const TEST = d.test === true;

// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.date === undefined && d.close_time === undefined) {
    node.warn('market_open: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 wording, verbatim. The early-close line is additive: v2 had no equivalent
// because the integration did not yet publish close_time.
let message = 'NYSE is now open. Portfolio tracking begins.';
if (d.early_close) message += `\nEarly close today at ${d.close_time} ET.`;

msg.payload = {
    title:   '\u{1F514} Market Open',
    message: message,
    color:   'green',
    channel: 'Stocks',
    test:    TEST
};
return msg;

const d = msg.payload || {};
const TEST = d.test === true;

// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.new_value === undefined) {
    node.warn('eod2_summary: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 parity: "old \u2192 new / P/L: \u00b1$x (\u00b1y%) / S&P 500 was z% today".
function fmtMoney(val) {
    if (val == null || isNaN(val)) return 'unavailable';
    return '$' + Math.abs(Math.round(val)).toLocaleString('en-US');
}

const oldVal = Number(d.previous_value);
const newVal = Number(d.new_value);
const pl     = Number(d.day_change);
const plPct  = Number(d.day_change_pct);

const leadPct = flow.get('lead_pct');
const badge = (leadPct != null && !isNaN(leadPct)) ? (leadPct >= 0 ? '\u{1F7E2}' : '\u{1F534}') : '\u{1F4CA}';
const leadStr = (leadPct != null && !isNaN(leadPct))
    ? `${leadPct >= 0 ? '+' : ''}${Number(leadPct).toFixed(2)}%` : 'unavailable';

const havePL = !isNaN(pl);
const plSign = havePL ? (pl >= 0 ? '+' : '-') : '';
const plPctStr = !isNaN(plPct) ? ` (${plSign}${Math.abs(plPct).toFixed(2)}%)` : '';
const plStr = havePL ? `${plSign}${fmtMoney(pl)}${plPctStr}` : 'unavailable';

const lead = !isNaN(oldVal) ? fmtMoney(oldVal) : fmtMoney(newVal);
const changeStr = (!isNaN(oldVal) && !isNaN(newVal)) ? ` \u2192 ${fmtMoney(newVal)}` : '';

let message = `${lead}${changeStr}\nP/L: ${plStr}\nS&P 500 was ${leadStr} today`;
if (d.deferred) message += '\n(held from overnight)';

msg.payload = {
    title:   `${badge} 401k Updated`,
    message: message,
    color:   havePL ? (pl >= 0 ? 'green' : 'red') : 'red',
    channel: 'Stocks',
    test:    TEST
};
return msg;

const d = msg.payload || {};
const TEST = d.test === true;

// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.amount === undefined) {
    node.warn('paycheck_detected: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 parity, including the exact window wording.
const fmt = n => '$' + Math.round(n).toLocaleString('en-US');
const inWindow = d.in_pay_window === true;
const windowText = inWindow ? ' \u2014 lines up with payday' : ' \u2014 outside normal pay window';

msg.payload = {
    title:   inWindow ? '\u{1F4B0} Likely Paycheck' : '\u{1F4B5} Large Cash Increase',
    message: 'Estimated paycheck: ' + fmt(Number(d.amount)) + windowText,
    color:   '#2E7D32',
    channel: 'Network Restored',
    test:    TEST
};
return msg;

const d = msg.payload || {};
const TEST = d.test === true;

// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.status !== 'online' && d.status !== 'offline') {
    node.warn('monarch_status: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 watchdog wording. The integration decides the transition, so the flow no
// longer has to debounce unavailable/unknown states itself.
if (d.status === 'online') {
    msg.payload = {
        title:   '\u2705 Monarch Integration Restored',
        message: 'Monarch sensors are reporting again. Holdings and the P&L sensor are back.',
        color:   '#2E7D32',
        channel: 'Flow Errors'
    };
} else {
    msg.payload = {
        title:   '\u26A0\uFE0F Monarch Integration Down',
        message: 'Monarch sensors are unavailable \u2014 portfolio holdings and the P&L sensor will read $0 until it reconnects. Reload the integration (Settings \u2192 Devices & Services \u2192 Reload) or re-authenticate.',
        color:   '#D32F2F',
        channel: 'Flow Errors'
    };
}
msg.payload.test = TEST;
return msg;

const d = msg.payload || {};
const TEST = d.test === true;

// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.symbol === undefined && d.error === undefined) {
    node.warn('finnhub_error: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 raised node.error here and the catch-all formatted it; the integration
// publishes the failure directly, so it is formatted in place. The 2h dedup is
// carried over from v2's "Error Dedup + Format".
msg.payload = {
    title:   '\u26A0\uFE0F Finnhub Self-Test Failed',
    message: `Self-test failed for ${d.symbol}: ${d.error}\nQuotes may be broken today.`,
    color:   '#D32F2F',
    channel: 'Flow Errors',
    test:    TEST,
    dedupKey: 'finnhub_error',
    cooldownMs: 2 * 60 * 60 * 1000
};
return msg;

const d = msg.payload || {};
const TEST = d.test === true;

// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.symbol === undefined || d.price === undefined) {
    node.warn('finnhub_ok: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 only notified on a *manual* self-test; a passing scheduled test was silent.
// Same here: stay quiet unless this was fired from the integration's test button.
if (!TEST) return null;

msg.payload = {
    title:   '\u2705 Finnhub API OK',
    message: `HTTP 200 - ${d.symbol} $${Number(d.price).toFixed(2)}`,
    color:   '#2E7D32',
    channel: 'Flow Errors',
    test:    TEST
};
return msg;

// Exit gate: identical-message collapse, burst limit, hourly ceiling.
//
// State lives in GLOBAL context, not flow context. If this flow ends up
// deployed more than once -- or the Home Assistant websocket node leaks a
// subscription across a redeploy, delivering the same event several times --
// every copy then shares one budget instead of each getting its own.
const p = msg.payload;
if (!p || !p.title) return null;

const now = Date.now();
if (p.test) p.title = '\u{1F9EA} TEST: ' + p.title;

const KEY = 'ha_stock_app_notify';
const st = global.get(KEY) || {seen: {}, burst: [], hourly: []};
st.seen = st.seen || {}; st.burst = st.burst || []; st.hourly = st.hourly || [];

// Identical-message collapse. Test events get a short window rather than an
// exemption: pressing the test button twice on purpose should work, but one
// press must never arrive five times.
const key = p.dedupKey || ('title:' + p.title);
const window = p.test ? 5000 : (p.cooldownMs || 10 * 60 * 1000);
for (const k of Object.keys(st.seen)) if (now - st.seen[k] > 86400000) delete st.seen[k];
if (st.seen[key] && now - st.seen[key] < window) {
    global.set(KEY, st);
    node.status({fill: 'grey', shape: 'ring', text: 'duplicate collapsed'});
    return null;
}

// Burst limit: everything, tests included.
st.burst = st.burst.filter(t => now - t < 60000);
if (st.burst.length >= 5) {
    global.set(KEY, st);
    node.status({fill: 'red', shape: 'ring', text: 'burst limit'});
    node.warn('Burst limit: >5 notifications in 60s. Dropping: ' + p.title);
    return null;
}

// Hourly ceiling for real traffic.
st.hourly = st.hourly.filter(t => now - t < 3600000);
if (!p.test && st.hourly.length >= 12) {
    global.set(KEY, st);
    node.status({fill: 'red', shape: 'ring', text: 'hourly ceiling'});
    node.warn('Hourly ceiling reached; suppressing: ' + p.title);
    return null;
}

st.seen[key] = now;
st.burst.push(now);
if (!p.test) st.hourly.push(now);
global.set(KEY, st);

delete p.dedupKey; delete p.cooldownMs;
node.status({fill: 'green', shape: 'dot', text: p.title.slice(0, 28)});
return msg;
